// Everything a site form can say arrives here as one of four kinds:
//   contact      a message from the contact form
//   newsletter   a request to subscribe (starts the double opt-in)
//   confirm      the button behind the mailed link was pressed
//   unsubscribe  the same link, the other verb
// A submission missing what its kind needs leaves as route 'invalid' and is
// answered 422. Nothing here throws, so a bad POST does not page the error
// workflow.
//
// The time is this workflow's clock, never the sender's: the resend gate
// further on counts from it.
const b = $('When Form Is Sent').first().json.body || {};
const clip = (v, n) => String(v ?? '').trim().slice(0, n);

const kind = clip(b.kind, 20);
const email = clip(b.email, 200).toLowerCase();
const name = clip(b.name, 120);
const parts = name.split(/\s+/).filter(Boolean);
const message = clip(b.message, 4000);
const token = clip(b.token, 64);
const tokenOk = /^[A-Za-z0-9-]{16,64}$/.test(token);
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

let route = 'invalid';
if (kind === 'contact' && emailOk && message) route = 'contact';
if (kind === 'newsletter' && emailOk && tokenOk) route = 'newsletter';
if ((kind === 'confirm' || kind === 'unsubscribe') && tokenOk) route = 'token';

return [{
  json: {
    route,
    kind,
    received_at: $now.toISO(),
    email,
    name,
    first_name: parts[0] || '',
    surname: parts.slice(1).join(' '),
    message,
    path: clip(b.path, 200),
    token: tokenOk ? token : '',
  },
}];

// Decide whether this request earns a confirmation mail.
//
// The form is public, so anyone can type anyone's address into it. Three
// limits keep that from becoming a way to mail strangers:
//   - a confirmed address gets nothing
//   - an unconfirmed one gets one mail per resend_after_h, and at most
//     max_mails_unconfirmed in total until it confirms
//   - the whole list gets at most max_mails_per_hour, so a flood of made-up
//     addresses stops itself before it empties the mail quota
// The form answers the same in every case: it never tells a visitor whether
// an address is on the list.
const cfg = $('Set Site Config').first().json;
const form = $('Validate Form').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.email);
const row = rows.find((r) => String(r.email).trim().toLowerCase() === form.email) || {};

const HOUR = 3600e3;
const age = (v) => { const n = Date.parse(String(v || '')); return Number.isFinite(n) ? Date.now() - n : Infinity; };
const mails = Number(row.mails) || 0;
// requested_at moves only when a mail goes out, so this counts mails.
const sentThisHour = rows.filter((r) => age(r.requested_at) < HOUR).length;

let why = '';
if (row.state === 'confirmed') why = 'already confirmed';
else if (age(row.requested_at) < cfg.resend_after_h * HOUR) why = 'asked recently';
else if (mails >= cfg.max_mails_unconfirmed) why = 'mail limit for this address';
else if (sentThisHour >= cfg.max_mails_per_hour) why = 'hourly limit for the list';

return [{ json: { due: why === '', why, mails: mails + 1 } }];

// What a token may change on the one Subscribers row that owns it.
//   confirm      pending -> confirmed, while the request is younger than
//                confirm_within_days. Already confirmed is a quiet yes. An
//                unsubscribed row is not revived by an old link: subscribing
//                again starts from the form and gets a fresh token.
//   unsubscribe  anything -> unsubscribed, at any age, and repeating it is a
//                quiet yes.
// 'changed' is false on a repeat, so the contact book is written once.
const cfg = $('Set Site Config').first().json;
const form = $('Validate Form').first().json;
const row = $input.first().json || {};

const invalid = [{ json: { valid: false, changed: false } }];
if (!row.email || String(row.token || '') !== form.token) return invalid;

const DAY = 86400e3;
const asked = Date.parse(String(row.requested_at || ''));
const now = $now.toISO();
let state = String(row.state || '');
let confirmed_at = String(row.confirmed_at || '');
let unsubscribed_at = String(row.unsubscribed_at || '');
let mails = Number(row.mails) || 0;
let changed = false;

if (form.kind === 'confirm') {
  if (state === 'unsubscribed') return invalid;
  if (state !== 'confirmed') {
    if (!(Date.now() - asked < cfg.confirm_within_days * DAY)) return invalid;
    state = 'confirmed'; confirmed_at = now; mails = 0; changed = true;
  }
} else if (state !== 'unsubscribed') {
  state = 'unsubscribed'; unsubscribed_at = now; changed = true;
}

return [{
  json: { valid: true, changed, token: form.token, email: String(row.email).trim().toLowerCase(), state, confirmed_at, unsubscribed_at, mails },
}];

// What the contact book learns from a message: who wrote, and about what.
const form = $('Validate Form').first().json;
return [{
  json: {
    change: {
      email: form.email,
      first_name: form.first_name,
      surname: form.surname,
      group_add: 'contact',
      group_remove: '',
      association: 'site-contact',
      topic: 'Site message · ' + (form.path || '/'),
      note: form.message.slice(0, 500),
    },
  },
}];

// What the contact book learns from a confirm or an unsubscribe: the address
// joins or leaves the group 'newsletter'.
const t = $('Decide Token Change').first().json;
const joined = t.state === 'confirmed';
return [{
  json: {
    change: {
      email: t.email,
      first_name: '',
      surname: '',
      group_add: joined ? 'newsletter' : '',
      group_remove: joined ? '' : 'newsletter',
      association: 'site-newsletter',
      topic: joined ? 'Newsletter · confirmed' : 'Newsletter · unsubscribed',
      note: '',
    },
  },
}];

// Build the Entries write. The next node auto-maps and matches on email, so it
// writes exactly the keys emitted here and nothing else.
//   known contact  only what changed: groups, last_topic, contact_updated_at.
//                  Their name, status and notes were curated elsewhere and a
//                  web form is not a reason to overwrite them.
//   new contact    a full starting row.
// Someone leaving the newsletter who was never in the book is not added to it.
const { change: c, ...cur } = $json;
const known = !!cur.email;

if (!known && !c.group_add) return [];

const groups = new Set(String(cur.groups || '').split(',').map((g) => g.trim()).filter(Boolean));
if (c.group_add) groups.add(c.group_add);
if (c.group_remove) groups.delete(c.group_remove);

const now = $now.toISO();
const row = {
  email: known ? cur.email : c.email,
  groups: [...groups].join(', '),
  last_topic: c.topic,
  contact_updated_at: now,
};
if (!known) {
  Object.assign(row, {
    first_name: c.first_name,
    surname: c.surname,
    status: 'lead',
    association: c.association,
    notes: c.note,
    contact_created_at: now,
  });
}
return [{ json: row }];

// Briefing plugin: the SITE INBOX section.
// Contract: 05_daily-briefing/docs/briefing-plugin-spec.md
//
// PLAIN TEXT ONLY, never HTML. The briefing escapes centrally, and everything
// printed here was typed by a stranger.
//
// Nothing pings when a form is sent; this section is the only place a message
// or a signup is announced, so it prints the message itself, not a count.
const MAX_MSGS = 5;      // each can run to MSG_CHARS; the 4096 cap is shared
const MSG_CHARS = 400;
const MAX_SUBS = 10;

const input = $('When Called for Briefing').first().json;
const tz = input.tz || 'UTC';
const since = Date.now() - (Number(input.window_hours) || 24) * 3600e3;

const ts = (v) => { const n = Date.parse(String(v || '')); return Number.isFinite(n) ? n : null; };
const fresh = (v) => { const n = ts(v); return n !== null && n >= since; };
const hhmm = (v) => new Date(ts(v)).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz });
const flat = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();

const messages = $('Get Messages in Sheets').all().map((i) => i.json).filter((r) => r && r.email && fresh(r.ts));
const subs = $('Get Subscribers for Briefing').all().map((i) => i.json).filter((r) => r && r.email);

messages.sort((a, b) => ts(b.ts) - ts(a.ts));
const msgItems = messages.slice(0, MAX_MSGS).map((m) => {
  const who = flat(m.name) ? flat(m.name) + ' <' + flat(m.email) + '>' : flat(m.email);
  const body = flat(m.message);
  const text = body.length > MSG_CHARS ? body.slice(0, MSG_CHARS) + '…' : body;
  return who + ' · ' + hhmm(m.ts) + ' · ' + (flat(m.path) || '/') + '\n    ' + text;
});
if (messages.length > MAX_MSGS) msgItems.push('+' + (messages.length - MAX_MSGS) + ' more in the Messages tab');

// One row per address, so one line per address: the latest thing that happened.
const events = [];
for (const s of subs) {
  const from = flat(s.path) ? ' · from ' + flat(s.path) : '';
  if (s.state === 'unsubscribed' && fresh(s.unsubscribed_at)) events.push({ at: ts(s.unsubscribed_at), text: flat(s.email) + ' · unsubscribed' });
  else if (s.state === 'confirmed' && fresh(s.confirmed_at)) events.push({ at: ts(s.confirmed_at), text: flat(s.email) + ' · confirmed' + from });
  else if (s.state === 'pending' && fresh(s.requested_at)) events.push({ at: ts(s.requested_at), text: flat(s.email) + ' · asked, not confirmed yet' + from });
}
events.sort((a, b) => b.at - a.at);
const subItems = events.slice(0, MAX_SUBS).map((e) => e.text);
if (events.length > MAX_SUBS) subItems.push('+' + (events.length - MAX_SUBS) + ' more in the Subscribers tab');

const count = (state) => subs.filter((s) => s.state === state).length;
const totals = count('confirmed') + ' confirmed · ' + count('pending') + ' pending · ' + count('unsubscribed') + ' unsubscribed';
if (subItems.length) subItems.push('List: ' + totals);

// Always exactly one item: zero items is indistinguishable from a crash.
return [{
  json: {
    key: 'reach',
    icon: '📬',
    title: 'SITE INBOX',
    blocks: [
      { heading: 'Messages', items: msgItems },
      { heading: 'Newsletter', items: subItems },
    ],
    empty: 'Nothing new · list: ' + totals,
  },
}];
